import { Plugin, PluginContext } from '@lemur-engine/core';

export default class {{name}}Plugin implements Plugin {
  constructor(private context: PluginContext) {}

  async initialize(): Promise<void> {
    this.context.logger.info('Inicializando {{name}} plugin');
  }

  async start(): Promise<void> {
    this.context.logger.info('Iniciando {{name}} plugin');
  }

  async stop(): Promise<void> {
    this.context.logger.info('Deteniendo {{name}} plugin');
  }
}

import { createMockPluginContext } from '@lemur-engine/testing';
import {{name}}Plugin from '../src';

describe('{{name}}Plugin', () => {
  let plugin: {{name}}Plugin;
  let context: any;

  beforeEach(() => {
    context = createMockPluginContext();
    plugin = new {{name}}Plugin(context);
  });

  it('debería inicializarse correctamente', async () => {
    await plugin.initialize();
    expect(context.logger.info).toHaveBeenCalledWith('Inicializando {{name}} plugin');
  });

  it('debería iniciar correctamente', async () => {
    await plugin.start();
    expect(context.logger.info).toHaveBeenCalledWith('Iniciando {{name}} plugin');
  });

  it('debería detenerse correctamente', async () => {
    await plugin.stop();
    expect(context.logger.info).toHaveBeenCalledWith('Deteniendo {{name}} plugin');
  });
});

